args:
Write-Host 'QUIZ: sincronizacao automatica ativa (modo silencioso).' -ForegroundColor Green
$arquivos = @('prova-publicada.json','app.js','index.html','painel.html','login.html','escola.html','style.css','firebase.json','firestore.rules','apresentacao.html')
$ultimoFetch = [datetime]::MinValue
$ultimoAviso = ''
while ($true) {
  Start-Sleep -Seconds 10
  $pendentes = @(git status --porcelain -- $arquivos)
  if ($LASTEXITCODE -ne 0) { if ($ultimoAviso -ne 'status') { Write-Host 'QUIZ: erro ao consultar arquivos.' -ForegroundColor Red; $ultimoAviso='status' }; continue }
  if ($pendentes.Count -gt 0) {
    git add -- $arquivos
    if ($LASTEXITCODE -ne 0) { if ($ultimoAviso -ne 'add') { Write-Host 'QUIZ: erro ao preparar arquivos.' -ForegroundColor Red; $ultimoAviso='add' }; continue }
    git diff --cached --quiet
    if ($LASTEXITCODE -eq 1) {
      git -c gc.auto=0 commit -m 'Atualizacao automatica do sistema'
      if ($LASTEXITCODE -ne 0) { if ($ultimoAviso -ne 'commit') { Write-Host 'QUIZ: erro ao registrar alteracoes.' -ForegroundColor Red; $ultimoAviso='commit' }; continue }
    }
  }
  $agora = Get-Date
  if (($agora - $ultimoFetch).TotalSeconds -ge 60) {
    git -c gc.auto=0 -c fetch.writeCommitGraph=false fetch origin main --quiet
    if ($LASTEXITCODE -ne 0) { if ($ultimoAviso -ne 'fetch') { Write-Host 'QUIZ: sem acesso ao GitHub; nova tentativa em breve.' -ForegroundColor Yellow; $ultimoAviso='fetch' }; continue }
    $ultimoFetch = $agora
  }
  git merge-base --is-ancestor origin/main HEAD
  if ($LASTEXITCODE -ne 0) { if ($ultimoAviso -ne 'divergencia') { Write-Host 'QUIZ: commits remotos pendentes. Publicacao pausada; integrar manualmente antes de enviar.' -ForegroundColor Yellow; $ultimoAviso='divergencia' }; continue }
  git rev-list --count origin/main..HEAD | ForEach-Object { $quantidade = [int]$_ }
  if ($LASTEXITCODE -ne 0) { continue }
  if ($quantidade -gt 0) {
    git -c gc.auto=0 push origin main
    if ($LASTEXITCODE -eq 0) { Write-Host 'QUIZ: Publicacao concluida.' -ForegroundColor Green; $ultimoAviso='' }
    elseif ($ultimoAviso -ne 'push') { Write-Host 'QUIZ: envio nao concluido; nova tentativa em breve.' -ForegroundColor Yellow; $ultimoAviso='push' }
  } else { $ultimoAviso='' }
}
